fname = matlab.desktop.editor.getActiveFilename;  % full filename (empty if none)
folder = fileparts(fname); 
xclFile = fullfile(folder, "CoH Data.xlsx") %[output:60fb26ab]
% filename = "/Users/ernesto/MATLAB-Drive/MHA Support/JAM/CoH Data.xlsx"; %[control:filebrowser:2720]{"position":[14,73]}
T = readtable(xclFile); %[output:4ecbbd79]
T.Properties.VariableNames{3} = 'Quiz'; % rename column

T.Quiz = categorical(T.Quiz,unique(T.Quiz), ["Post" "Pre"],ordinal=true ); 
T.Quiz = reordercats(T.Quiz,["Pre" "Post"]);
T.Condition = categorical(T.Condition,[0 1],["Control" "Experiment"]) %[output:6fb439c3]
%%
figure; %[output:88a40063]
hbc = boxchart(T.Condition, T.Score,GroupByColor = T.Quiz,Notch="off"); %[output:88a40063]
ylim([0 10]) %[output:88a40063]
legend(categories(T.Quiz),Location="southeast") %[output:88a40063]
%%
stats = groupsummary(T,["Condition" "Quiz"],["mean" "median"],"Score") %[output:87ed90a3]
%%
figure; %[output:3edc0eaa]
hbc = violinplot(T.Condition, T.Score,GroupByColor = T.Quiz); %[output:3edc0eaa]
ylim([-1 15]) %[output:3edc0eaa]
legend(categories(T.Quiz),Location="southeast") %[output:3edc0eaa]
%%
figure; %[output:57c8a55e]

% create boxplot
hbc = boxchart(T.Condition, T.Score,GroupByColor = T.Quiz,Notch="off"); %[output:57c8a55e]
ylim([0 10]) %[output:57c8a55e]
ylabel('Score') %[output:57c8a55e]


% plot data points
hold on %[output:57c8a55e]
offset = 0.15; % offsets x-position of data points
sz = 15; % marker size
xjw = 0.15; % jitter width
mfa = 0.1; % marker face alpha

C = colororder;

swarmchart(single(hbc(1).XData)-offset,hbc(1).YData,sz,'filled', ... %[output:57c8a55e]
    XJitter='density',... %[output:57c8a55e]
    XJitterWidth=xjw, ... %[output:57c8a55e]
    MarkerFaceColor='k',... %[output:57c8a55e]
    MarkerFaceAlpha=mfa) %[output:57c8a55e]

swarmchart(single(hbc(2).XData)+offset,hbc(2).YData,sz,'filled', ... %[output:57c8a55e]
    XJitterWidth=xjw, ... %[output:57c8a55e]
    MarkerFaceColor='k',...C(2,:),... %[output:57c8a55e]
    MarkerFaceAlpha=mfa) %[output:57c8a55e]

% move scatter plots to the back layer (under box plots)
ax = gca;
chH = ax.Children; 
ax.Children = flipud(chH); %[output:57c8a55e]

% add legend
legend(hbc, categories(T.Quiz),Location="southeast") %[output:57c8a55e]
%%


%%
hbc(1) %[output:9c86c5db]
%%
prepostFile = fullfile(folder, "Post-Pre.xlsx");
T2 = readtable(prepostFile); %[output:45ebc5b9]
T2.Condition = categorical(T2.Condition,[0 1],["Control" "Experiment"]);
%%
figure; %[output:191a2b2e]
boxchart(T2.Condition,T2.Post_Pre); %[output:191a2b2e]
hold on  %[output:191a2b2e]
swarmchart(T2.Condition,T2.Post_Pre, ... %[output:191a2b2e]
    'filled', ... %[output:191a2b2e]
    XJitter='density',... %[output:191a2b2e]
    XJitterWidth=xjw, ... %[output:191a2b2e]
    MarkerFaceColor='k',... %[output:191a2b2e]
    MarkerFaceAlpha=mfa) %[output:191a2b2e]
ylabel('Score Difference') %[output:191a2b2e]
